 return <div className="workspace"><aside className="sidebar"><a className="brand" href={stt?"/stt":"/"} onClick={e=>{e.preventDefault();navigate(()=>{window.location.href=stt?"/stt":"/";});}}><span className="brand-icon"><AudioLines size={23}/></span><span>{stt?"STT 작업실":"회의록 작업실"}<small>{stt?"SPEECH TO TEXT":"MEETING WORKSPACE"}</small></span></a><button className={`nav-item ${view==="new"?"active":""}`} onClick={()=>navigate(()=>{setView("new");setMeta(newMeeting());setJob(null);})}><Plus size={18}/>{stt?"새 녹취 만들기":"새 회의 만들기"}</button><div className="nav-caption">{serverProcessing?"서버 보관 작업":"나의 작업"}</div><div className="job-nav">{jobs.length?jobs.map(j=><button key={j.id} className={`job-link ${job?.id===j.id?"selected":""}`} onClick={()=>navigate(()=>{run(()=>load(j.id));})}><FileText size={17}/><span>{j.kind==="call"&&<em className="kind-badge">통화</em>}{title(j)}<small>{statusLabel(j.state)}{listProgress(j)} · {new Date(j.created_at).toLocaleDateString("ko-KR")}</small></span></button>):<p className="empty-nav">{stt?"첫 녹취를 만들어 보세요.":"첫 회의의 기록을 남겨 보세요."}</p>}</div><button className={`nav-item settings-nav ${view==="settings"?"active":""}`} onClick={()=>navigate(()=>setView("settings"))}><Monitor size={18}/>{serverProcessing?"서버 처리 상태":"PC 연결 및 설정"}<span className={`dot ${connected?"online":""}`}/></button><div className="profile"><span>{displayName[0]}</span><div>{displayName}<small>개인 전용 작업 공간</small></div></div></aside><div className="main-shell"><nav className="workflow-nav" aria-label="출력 방식"><a href="/" aria-current={!stt?"page":undefined} onClick={e=>{e.preventDefault();navigate(()=>{window.location.href="/";});}}><FileText size={16}/>회의록</a><a href="/stt" aria-current={stt?"page":undefined} onClick={e=>{e.preventDefault();navigate(()=>{window.location.href="/stt";});}}><AudioLines size={16}/>STT · 녹취만</a></nav><header className="topbar"><div>작업 공간 <ChevronRight size={14}/><strong>{view==="new"?stt?"새 녹취":"새 회의":view==="settings"?serverProcessing?"서버 처리":"PC 연결":job?title(job):stt?"녹취 검토":"회의 검토"}</strong></div><span className="private"><span className="dot online"/>비공개 · 나만 접근</span></header><div className="mobile-job-picker"><label htmlFor="recent-meeting-select">{stt?"최근 녹취":"최근 회의"}</label><select id="recent-meeting-select" aria-label={stt?"저장한 녹취 열기":"저장한 회의 열기"} value={view==="job"?job?.id??"":""} onChange={e=>{const id=e.target.value;if(id)navigate(()=>{run(()=>load(id));});}}><option value="">{stt?"저장한 녹취 열기":"저장한 회의 열기"}</option>{jobs.map(j=><option key={j.id} value={j.id}>{j.kind==="call"?"통화 · ":""}{title(j)} · {new Date(j.created_at).toLocaleDateString("ko-KR")} · {statusLabel(j.state)}</option>)}</select></div><main><fieldset className="workspace-content" disabled={busy}>
 {serverProcessing&&<><div className="banner server-processing" role="status"><Monitor size={18}/><span><strong>{serverStatus}</strong> · {apiSpeech?"OpenAI API로 전사하고 서버에서 화자를 분석합니다.":"음성은 서버 작업기가 처리합니다."} PC 연결 코드는 필요하지 않습니다.</span><button onClick={()=>navigate(()=>setView("settings"))}>상태 보기</button></div><p className="storage-note">업로드가 완료된 작업은 서버에 보관됩니다. 다른 기기에서도 같은 소유자 계정으로 로그인해 저장된 원본과 TXT를 내려받을 수 있습니다.</p></>}
 {apiPaused&&<div className="banner error api-pause" role="alert"><AlertCircle size={18}/><span><strong>API 음성 처리 중단</strong><br/>{apiPauseMessage}<small>새 파일은 보관할 수 있지만 해제 전에는 처리를 시작하지 않습니다. 저장된 TXT와 원본 다운로드는 유지됩니다.</small></span></div>}
 {(apiSpeech||apiPaused)&&<div className="api-credit-note"><strong>{apiSpeech?`전사 모델: ${worker.capabilities.speech}`:"API 전사 상태 확인 필요"}</strong><p>ChatGPT 구독 대화 토큰이 아닌 OpenAI API를 사용합니다. 사용자가 확인한 무료 API 크레딧과 결제 설정을 전제로 합니다.</p><p>현재 잔액: 확인할 수 없음 · 앱은 결제·자동충전 설정을 변경하지 않으며, 무료 잔액만 선택해 결제하도록 강제할 수 없습니다.</p></div>}
 {(metaInference||metaBlocked)&&<div className="api-credit-note"><strong>회의 정보 추정{metaInference?`: ${metaCodex?"ChatGPT 구독(Codex)":worker.capabilities.meta_inference.slice(4)}`:""}</strong><p>{metaCodex?"회의 정보 추정은 OpenAI API가 아니라 ChatGPT 구독의 Codex로 합니다. 회의록 작업마다 1번 부르고 API 비용은 들지 않지만, 구독 사용 한도를 함께 씁니다.":"회의 정보 추정에 텍스트 모델도 사용합니다. 회의록 작업마다 1번 부르고, 작업별 비용 상한 안에서만 부릅니다."}</p>{metaBlocked&&<p className="field-source missing">{metaCodex?"회의 정보 자동 추정을 잠시 쉬는 중입니다(구독 사용 한도, 로그인, 응답 지연). 녹취는 정상이고, 몇 분 뒤 자동으로 다시 시도합니다.":"회의 정보 자동 추정 중단, 녹취는 정상입니다. 운영자가 확인한 뒤 다시 켭니다."}</p>}</div>}
 {session?.cloud_deletions_pending>0&&<div className="banner error"><AlertCircle size={18}/>일부 클라우드 음성 삭제를 재시도하고 있습니다. 이 창을 유지하거나 나중에 다시 연결해 주세요.</div>}{error&&<div role="alert" className="banner error"><AlertCircle size={18}/>{error}<button onClick={()=>setError("")}>닫기</button></div>}{notice&&<div role="status" className="banner success"><Check size={18}/>{notice}<button onClick={()=>setNotice("")}>닫기</button></div>}
 {view==="new"&&<><div className="page-heading"><div className="eyebrow">기록에 집중하는 시간</div><h1>{stt?"음성을, 읽을 수 있는 기록으로.":"회의의 끝을, 다음 시작으로."}</h1><p>{stt?"파일이나 녹음에서 녹취만 만들고, 확인한 원문을 TXT로 내려받으세요.":"음성을 전달하고, 확인한 내용으로 회의록을 완성하세요."}</p></div><div className={`create-grid ${stt?"stt-create":""}`}><section className="card input-card"><div className="section-heading"><span className="step-number">01</span><div><h2>{stt?"음성 파일 또는 녹음":"회의 음성"}</h2><p>파일을 올리거나 지금 녹음하세요.</p></div></div><div className="segmented"><button className={source==="file"?"selected":""} disabled={recording} onClick={()=>setSource("file")}><Upload size={17}/>파일 업로드</button><button className={source==="recording"?"selected":""} disabled={recording} onClick={()=>setSource("recording")}><Mic size={17}/>직접 녹음</button></div>
 {source==="file"?<><div className={`dropzone ${files.length?"has-file":""} ${dragActive?"drag-active":""}`} onDragEnter={e=>{e.preventDefault();if(busyRef.current)return;if(Array.from(e.dataTransfer.types).includes("Files")){dragDepth.current++;setDragActive(true);}}} onDragLeave={e=>{e.preventDefault();dragDepth.current=Math.max(0,dragDepth.current-1);if(!dragDepth.current)setDragActive(false);}} onDragOver={e=>{e.preventDefault();e.dataTransfer.dropEffect=!busyRef.current&&Array.from(e.dataTransfer.types).includes("Files")?"copy":"none";}} onDrop={e=>{e.preventDefault();e.stopPropagation();dragDepth.current=0;setDragActive(false);addFiles(Array.from(e.dataTransfer.files));}} aria-describedby="file-queue-hint"><div className="upload-mark"><Upload size={29}/></div><h3>{dragActive?"놓으면 파일 목록에 추가합니다.":stt?"음성 파일들을 여기에 놓으세요":"회의 음성 파일들을 여기에 놓으세요"}</h3><p id="file-queue-hint">여러 파일 선택 가능 · 선택과 드롭은 기존 목록에 추가됩니다.<br/>M4A, MP3, WAV, WEBM 등 · 파일별 최대 512MB / 4시간</p><button className="button secondary" onClick={()=>fileInput.current?.click()}><FolderOpen size={16}/>{files.length?"파일 더 추가":"파일 선택"}</button><input ref={fileInput} type="file" multiple accept=".m4a,.mp3,.wav,.webm,.ogg,.mp4,.flac,.aac" hidden onChange={e=>{const selected=Array.from(e.currentTarget.files??[]);e.currentTarget.value="";addFiles(selected);}}/></div>{files.length>0&&<section className="file-queue" aria-label="업로드 파일 목록"><div className="file-queue-heading"><strong>선택한 파일 {files.length}개</strong><span>각 파일을 독립 작업으로 순서대로 업로드합니다.</span></div><ul aria-label="선택한 파일">{files.map(row=><li key={row.id} aria-label={row.file.name} data-upload-status={row.status} className={`file-queue-row ${row.status}`}><div className="file-queue-main"><strong className="file-queue-name">{row.file.name}</strong><small>{fileSize(row.file.size)} · {queueStateLabels[row.status]}{["uploading","verifying"].includes(row.status)?` · ${row.progress}%`:""}</small>{!stt&&row.status!=="invalid"&&<p className="file-queue-meta">{filenameDatetime(row.file.name)}</p>}{row.warning&&<p className="file-queue-warning">{row.warning}</p>}{row.error&&<p className="file-queue-error" role="alert">{row.error}</p>}{["checking","uploading","verifying"].includes(row.status)&&<progress aria-label={`${row.file.name} 업로드 진행률`} max={100} value={row.status==="checking"?undefined:row.progress}/>}</div><div className="file-queue-actions">{row.status==="failed"&&<button className="text-link" disabled={busy} onClick={()=>submitFiles(row.id)}><RefreshCw size={13}/>다시 시도</button>}{row.jobId&&(row.status==="complete"||row.status==="duplicate")&&<button className="text-link" disabled={busy} onClick={()=>navigate(()=>{run(()=>load(row.jobId!));})}>작업 열기<ChevronRight size={13}/></button>}<button className="icon-button" disabled={busy} aria-label={`${row.file.name} 목록에서 제거`} title="목록에서만 제거하며 업로드된 작업은 유지합니다." onClick={()=>removeFile(row.id)}><Trash2 size={15}/></button></div></li>)}</ul>{!stt&&<p className="file-queue-hint">회의 일시는 파일마다 이름에서 따로 읽습니다. 다시 시도는 해당 파일의 첫 업로드 시작 당시 회의 정보를 유지합니다.</p>}</section>}</>:<div className="recorder"><div className={`mic-orb ${recording?"recording":""}`}><Mic size={32}/></div><h3>{recording?stamp(elapsed*1000):recordBlob?partial?"부분 녹음이 보존되었습니다":"녹음이 준비되었습니다":stt?"지금 음성을 기록하세요":"회의를 바로 기록하세요"}</h3><p>{recording?`브라우저에 ${savedChunks}개 조각 저장 · 종료 후 처리`:"마이크 권한이 필요합니다. 녹음 중 이 탭을 유지해 주세요."}</p>{recording?<button className="button danger" onClick={()=>recorder.current?.stop()}><Square size={15}/>녹음 종료</button>:<button className="button secondary" onClick={startRecording} disabled={busy}><Mic size={16}/>{recordBlob?"다시 녹음":"녹음 시작"}</button>}{recordBlob&&<div className="recording-result"><audio src={recordUrl} controls/><a className="text-link" download={recordingName} href={recordUrl}><Download size={15}/>녹음 원본 내려받기</a></div>}{recoveries.length>0&&!recording&&<details><summary>보존된 녹음 {recoveries.length}개</summary>{recoveries.map(r=><div className="recovery" key={r.id}><span>{new Date(r.updated_at).toLocaleString("ko-KR")} · {r.partial?"부분 녹음 확인 필요":"완료된 녹음"}</span><button onClick={()=>run(async()=>{setRecordBlob(await restoreRecording(r.id,r.mime));recordId.current=r.id;setPartial(r.partial);})}>불러오기</button><button onClick={()=>run(async()=>{await deleteRecording(r.id);await recoverForMode();})}>삭제</button></div>)}</details>}</div>}
 <div className="input-footer"><Monitor size={16}/><span>{serverProcessing?apiSpeech?"OpenAI API 전사 · 서버 화자 분석":"서버 작업기가 보고한 설정으로 음성을 처리합니다.":"연결된 PC가 설정에 따라 로컬 또는 API로 처리합니다."}</span></div></section>{!stt&&<section className="card details-card"><div className="section-heading"><span className="step-number">02</span><div><h2>회의 정보</h2><p>{source==="file"?"회의 일시는 파일 이름에서, 참석자는 녹취에서 확인한 화자 이름에서 채웁니다. 여기에는 그 밖의 정보만 아는 만큼 적으세요.":"참석자는 녹취에서 확인한 화자 이름에서 채웁니다. 나머지는 아는 만큼 적으세요."}</p><p>채운 값은 작업의 회의 정보 탭에서 확인하고 저장합니다.{source==="file"?" 이어 올리는 기존 작업의 정보는 유지합니다.":""}</p></div></div><label>회의 유형</label><div className="type-options"><button className={type==="customer"?"selected":""} onClick={()=>setType("customer")}>고객 미팅</button><button className={type==="weekly"?"selected":""} onClick={()=>setType("weekly")}>주간회의</button></div>{type==="customer"&&<label className="checkbox"><input type="checkbox" checked={dev} onChange={e=>setDev(e.target.checked)}/>개발팀 답변 요청사항 포함</label>}<div className="metadata-form">{Object.entries(labels).filter(([k])=>(k!=="week"||type==="weekly")&&k!=="attendees"&&(k!=="datetime"||source==="recording")).map(([k,l])=><label key={k} className={k==="attendees"?"full":""}>{l}{k==="attendees"?<textarea value={meta.attendees} rows={2} placeholder="이름 직책 (회사) · 고객사 참석자부터 줄바꿈" onChange={e=>setMeta({...meta,attendees:e.target.value})}/>:<input type={k==="datetime"?"datetime-local":"text"} value={meta[k as keyof Metadata]} placeholder={metaInference&&!metaBlocked&&["organization","place","meeting_format"].includes(k)?"모르면 비워 두세요":k==="organization"?"예: 가나소프트":"선택 입력"} onChange={e=>setMeta({...meta,[k]:e.target.value})}/>}</label>)}</div>{metaInference&&!metaBlocked&&<p className="inline-note">고객사, 장소, 회의 형태는 녹취가 끝난 뒤 대화에서 추정해 회의 정보 탭에 보여 드립니다. 모르면 비워 두세요. 직접 적은 값이 우선합니다.</p>}</section>}</div><div className="submission-bar"><div><strong>{stt?"회의 정보 없이, 녹취만 만드세요.":"준비되면, 녹취부터 시작하세요."}</strong><p>{serverProcessing?apiPaused?"업로드만 보관하며 API 차단 해제 후 처리를 진행할 수 있습니다.":apiSpeech?"OpenAI API 전사와 서버 화자 분석을 순서대로 진행합니다.":"PC 연결 없이 서버 작업기가 순서대로 처리합니다.":"PC 설정에 따른 음성 처리 · API 사용 시 누적 비용 상한 적용."}</p></div><button className="button primary" disabled={busy||recording||(source==="file"?!waitingCount:!recordBlob)} onClick={submit}>{busy?(progress?`업로드 ${progress}%`:"처리 중…"):source==="file"?`${waitingCount}개 파일 업로드`:"녹취 만들기"}<ChevronRight size={17}/></button></div><div className="process-overview"><span><b>1</b>음성 전달</span><i/><span><b>2</b>녹취와 화자 검토</span><i/><span><b>3</b>{stt?"TXT 내려받기":"회의록 완성"}</span></div></>}
 {view==="settings"&&<><div className="page-heading"><div className="eyebrow">{serverProcessing?"SERVER SPEECH":"LOCAL WORKER"}</div><h1>{serverProcessing?"서버에서 음성을 처리합니다.":"이 PC를 작업실에 연결하세요."}</h1><p>{serverProcessing?"서버 작업기가 전사를 진행하고 화자를 분석합니다. 회의록 문장 생성은 아직 구성되지 않았으며 Notion 인증은 기존 PC에 유지됩니다.":stt?"PC가 음성 처리 작업을 가져와 녹취와 화자 정보를 만듭니다.":"PC가 음성 처리 작업을 가져오고, Notion 저장은 PC에서 실행합니다."}</p></div><section className="card settings-card"><h2><Monitor size={22}/>{serverProcessing?"서버 음성 작업기":"PC 연결"} <span className={`badge ${connected?"green":""}`}>{serverProcessing?serverStatus:connected?"연결됨":"연결 대기"}</span></h2>{serverProcessing?<p>최근 서버 응답을 기준으로 연결 상태를 표시합니다. 응답이 오래되면 연결됨으로 표시하지 않습니다. 작업별 오류는 해당 작업에서 확인하세요.</p>:<><p>PC 프로그램에서 이 사이트 주소와 5분 연결 코드를 입력하세요. 키와 화자 기준 데이터는 PC에만 보관됩니다.</p><button className="button primary" disabled={!processing?.pc_pairing_enabled} onClick={()=>run(async()=>{setCode((await api("pair","POST",{})).code);})}><Link2 size={16}/>연결 코드 만들기</button>{code&&<div className="pair-code"><code>{code}</code><span>5분 동안 유효 · PC 프로그램에 입력</span></div>}</>}<div className="settings-list"><div><span>{serverProcessing?"최근 서버 응답":"최근 PC 연결"}</span><strong>{worker?new Date(worker.last_seen).toLocaleString("ko-KR"):"아직 응답이 없습니다."}</strong></div>{[["음성 처리","speech"],["화자 분석","diarization"],...(!stt||serverProcessing?[["회의록 생성","generation"]]:[])].map(([l,k])=><div key={k}><span>{l}</span><strong>{serverProcessing&&k==="generation"?"미구성 · 녹취/TXT 이용 가능":worker?.capabilities?.[k]??"응답 확인 대기"}</strong></div>)}{(!stt||serverProcessing)&&<div><span>Notion 저장</span><strong>인증은 기존 PC에만 유지 · 서버 실행 없음</strong></div>}</div>{!serverProcessing&&<button className="text-link muted" disabled={!processing?.pc_pairing_enabled} onClick={()=>run(async()=>{await api("device","DELETE");setNotice("PC 연결을 해제했습니다.");await refresh();})}>PC 연결 해제</button>}</section><PushSettings/><section className="card settings-card"><h2>등록 화자</h2><p>{serverProcessing?"기존 PC의 화자 기준 음성과 특징값은 서버로 옮기지 않습니다. 서버 녹취의 화자 라벨과 이름은 직접 검토할 수 있습니다.":"확인한 단독 발화의 기준 음성과 특징값은 PC에만 저장됩니다. 이름은 후보 제안으로 사용하며 자동 확정하지 않습니다."}</p>{profiles.length?profiles.map(p=><div className="speaker-profile" key={p.person_id}><div><strong>{p.display_name}</strong><small>{p.role} {p.company} · v{p.profile_revision}</small></div>{!serverProcessing&&<button className="text-link muted" onClick={()=>run(async()=>{await api(`profiles/${p.person_id}`,"DELETE");setNotice("PC에 기준 음성·특징값 삭제를 예약했습니다.");})}>PC 프로필 삭제</button>}</div>):<p>{serverProcessing?"서버에서 실제 이름을 자동 확정하지 않습니다.":"아직 등록된 화자가 없습니다. 녹취 검토에서 확인한 구간을 등록하세요."}</p>}</section><section className="card settings-card"><h2>전사 용어 목록</h2><p>회의에 자주 나오는 제품명, 약어, 고유명사를 적어 두면 OpenAI API로 전사할 때 참고합니다. 한 줄에 하나씩 적으세요. 적은 용어는 음성과 함께 OpenAI 음성 API로 전송됩니다.</p><textarea className="keyword-list" aria-label="전사 용어 목록" rows={8} value={keywordText} disabled={savedKeywords===null||busy} placeholder={"회의록\nSTT\n화자 분리"} onChange={e=>setKeywordText(e.target.value)}/><div className="keyword-actions"><span className={keywordProblem||keywordLoadFailed?"keyword-problem":""} role={keywordProblem||keywordLoadFailed?"alert":undefined}>{keywordLoadFailed?"저장된 목록을 불러오지 못했습니다. 다시 불러온 뒤 고치세요.":keywordProblem||(savedKeywords===null?"저장된 목록을 불러오고 있습니다.":`${keywordTerms.length} / ${MAX_KEYWORDS}개. 아직 전사를 시작하지 않은 음성부터 적용되며, 이미 전사한 녹취는 바뀌지 않습니다.`)}</span>{keywordLoadFailed&&<button className="text-link" onClick={()=>setKeywordReload(n=>n+1)}>다시 불러오기</button>}<button className="button secondary" disabled={busy||!!keywordProblem||!keywordsChanged} onClick={saveKeywords}><Save size={16}/>용어 목록 저장</button></div></section><section className="card settings-card"><h2>처리 방식과 보관</h2><p>{serverProcessing?apiSpeech?"전사는 OpenAI API를 사용하고 화자 분리는 서버 모델로 실행합니다. API 사용이 차단되면 다른 모델이나 제공자로 자동 전환하지 않습니다.":"실제 음성 처리 방식은 위 작업기 보고를 확인하세요. 구독 대화 토큰을 음성 API로 사용하지 않습니다.":"구독의 음성 API 지원은 확인되지 않아 사용하지 않습니다. 로컬 전사 또는 PC에 설정한 지원 API만 사용합니다. API는 허용 경로와 작업별 비용 상한이 있어야 실행합니다."}</p><p>음성과 결과는 수동 삭제 전까지 보관됩니다. 자동 만료 삭제는 아직 활성화하지 않았습니다. 원본 파일은 이동하거나 수정하지 않습니다.</p></section></>}
 {view==="job"&&job&&<><div className="job-heading"><div><div className="eyebrow">{job.kind==="call"?"통화 녹취":stt?"STT · 녹취만":job.meeting_type==="weekly"?"주간회의":"고객 미팅"} · {new Date(job.created_at).toLocaleDateString("ko-KR")}</div><h1>{title(job)}</h1><p>{job.filename} · {job.duration?`${Math.round(job.duration/60)}분`:`${(job.byte_size/1024/1024).toFixed(1)} MB`}</p></div><span className={`badge ${job.state==="minutes_ready"?"green":""}`}>{statusLabel(job.state)}</span></div><section className="card status-card"><AudioLines size={22}/><div><strong>{statusLabel(job.state)}</strong><p>{job.error?.message??(job.state==="waiting_worker"?apiPaused?apiPauseMessage:serverProcessing?job.pending==="minutes"?"회의록 문장 생성이 구성되지 않아 이 작업은 대기 중입니다.":"서버 작업기가 순서대로 음성을 처리합니다. 위에서 현재 서버 응답 상태를 확인하세요.":"PC가 연결되면 작업을 이어서 시작합니다.":job.stage)} {job.speech_mode&&` · ${job.speech_mode}`}</p></div><button className="icon-button" aria-label="상태 새로고침" onClick={()=>run(()=>load(job.id))}><RefreshCw size={17}/></button><button className="text-link" disabled={apiPaused||dirty||!job.upload_complete||!!job.unresolved_external||job.state==="unknown_outcome"} title={apiPaused?apiPauseMessage:undefined} onClick={()=>{if(window.confirm(serverProcessing?apiSpeech?"설정된 OpenAI API로 음성을 다시 전사하고 서버에서 화자를 분석할까요? 이전 녹취 이력은 보존하고 작업별 비용 상한을 적용합니다.":"서버 작업기의 설정으로 음성을 다시 분석할까요? 이전 녹취 이력은 보존하고 새 버전을 만듭니다.":"PC에 설정된 방식으로 음성을 다시 분석할까요? 이전 녹취 이력은 보존하고 새 녹취 버전을 만듭니다. API가 설정되어 있으면 누적 비용 상한 안에서 API를 사용할 수 있습니다."))run(async()=>{await api(`jobs/${job.id}/reprocess-speech`,"POST",{expected_revision:job.revision});await load(job.id);setTab("transcript");});}}>음성 다시 분석</button>{(["failed","needs_setup","rate_limited","cancelled"].includes(job.state)||(job.state==="needs_review"&&job.error?.retryable))&&<button className="button secondary" disabled={apiPaused} title={apiPaused?apiPauseMessage:undefined} onClick={()=>run(async()=>{await api(`jobs/${job.id}/retry`,"POST",{});await load(job.id);})}>다시 시도</button>}<button className="text-link muted" onClick={()=>run(async()=>{await api(`jobs/${job.id}/cancel`,"POST",{});clearUploadResume(job.id);clearQueueJob(job.id);await load(job.id);})}>작업 취소</button></section><JobProgress key={job.id} job={job} title={title(job)} session={session} apiOrder={job.speech_mode?job.speech_mode.startsWith("api/"):apiSpeech}/>{!stt&&tab!=="info"&&(savedMissing.length>0||candidates.length>0)&&<div className="metadata-review-note" role="status"><span><strong>회의 정보 확인 필요</strong>{metaSuggestions.length>0&&` · 추정값 확인: ${metaSuggestions.map(x=>labels[x.key]).join(", ")}`}{candidates.length>0&&` · 참석 후보 ${candidates.length}명`}{manualMissing.length>0&&` · 직접 입력: ${manualMissing.map(k=>labels[k]).join(", ")}`}</span><button className="text-link" onClick={()=>selectTab("info")}>회의 정보 열기<ChevronRight size={13}/></button></div>}<div className="tabs"><button className={tab==="transcript"?"selected":""} onClick={()=>selectTab("transcript") }>녹취 검토 <small>v{job.transcript_revision}</small></button>{!stt&&<><button className={tab==="minutes"?"selected":""} onClick={()=>selectTab("minutes") }>회의록 <small>{job.draft?`v${job.draft.revision}`:"초안 대기"}</small></button><button className={tab==="info"?"selected":""} onClick={()=>selectTab("info") }>회의 정보{savedMissing.length>0&&<small>확인 {savedMissing.length}</small>}</button></>}</div>
 {tab==="transcript"&&<section className="card transcript-card"><div className="editor-toolbar"><div><h2>녹취와 화자를 확인하세요.</h2><p>원음을 들으며 텍스트·구간·화자를 수정하세요. 같은 라벨의 화자는 병합됩니다.{!stt&&" 화자 이름을 적고 저장하면 회의 정보의 참석자로 제안합니다."}</p></div><div className="button-row download-actions"><button className="text-link" disabled={!dirty||busy} onClick={()=>run(()=>load(job.id))}>변경 취소</button><button className="text-link" disabled={!segments.length||busy} onClick={()=>{setSegments(ss=>ss.map(x=>({...x,review_status:"confirmed"})));edit();}}>전체 검토 완료 표시</button><button className="button secondary" disabled={busy||!dirty||!job.transcript_revision} onClick={()=>saveTranscript()}><Save size={16}/>검토본 저장</button>{job.upload_complete&&<a className="button secondary" href={`/api/jobs/${job.id}/original`} download><Download size={16}/>원본 음성</a>}{(stt||serverProcessing)&&<button className="button primary" disabled={busy||dirty||!job.transcript_revision||!job.segments.length} onClick={downloadTranscript}><Download size={16}/>녹취 TXT 내려받기</button>}</div></div>{job.upload_complete&&<audio ref={audio} controls preload="metadata" src={`/api/jobs/${job.id}/audio`}/>} {job.pending==="transcribe"&&segments.length>0&&<div className="inline-note">이전 녹취 v{job.transcript_revision}을 유지한 채 새 음성 분석을 기다리고 있습니다. 새 결과는 별도 버전으로 저장합니다.</div>}{job.speech_mode?.includes("audio-clip-bounds")&&<div className="inline-note">이 API 녹취의 시간은 실제 전송한 음성 클립의 범위입니다. 단어별 시각이나 발화 경계의 정확도를 뜻하지 않습니다. 원음을 재생해 확인하세요.</div>}<SpeakerReview key={job.id} segments={segments} profiles={profiles} attendees={meta.attendees} canSave={!busy&&!!job.transcript_revision} otherEdits={dirty} activeFilter={speakerFilter} onApply={next=>{setSegments(next);edit();if(!busy&&job.transcript_revision)saveTranscript(next);}} onFilter={label=>{setSpeakerFilter(label);setVisibleSegments(50);}} onPlay={play}/>{speakerFilter&&<div className="speaker-filter-note"><span><strong>{speakerFilter}</strong> · {filteredSegments.length}개 구간 표시</span><button className="text-link" onClick={()=>{setSpeakerFilter(null);setVisibleSegments(50);}}>전체 녹취 보기</button></div>}{!job.diarization_complete&&segments.length>0&&<div className="inline-note">화자 분석이 완료되지 않았습니다. 미확인 화자를 검토해 주세요.</div>}{segments.length?filteredSegments.slice(0,visibleSegments).map((s,n)=><article className="segment" key={s.segment_id}><div className="segment-time"><button className="play-button" aria-label={`${stamp(s.start_ms)} 구간 재생`} onClick={()=>play(s)}><Play size={14}/></button><span>{stamp(s.start_ms)}</span></div><div className="segment-content">{s.timing_provenance==="audio_clip_bounds"&&<div className="segment-provenance">실제 전송 클립 범위 · 단어 시각 없음</div>}{s.timing_provenance==="manual"&&<div className="segment-provenance">사용자가 수정한 시간 범위</div>}{likelyMostlySilent(s)&&<div className="segment-provenance silence-hint">구간 길이에 비해 글이 적습니다. 대부분 말이 없는 구간일 수 있으니 원음을 확인하세요.</div>}<div className="segment-fields"><label>화자<input value={s.local_speaker_id} onChange={e=>change(s.segment_id,{local_speaker_id:e.target.value,speaker_name:"",confirmed_person_id:null,proposed_person_id:null,review_status:"unreviewed"})}/></label><label>{stt?"화자 이름 (선택)":"이름 직책 (회사)"}<input value={s.speaker_name} placeholder="미확인" onChange={e=>change(s.segment_id,{speaker_name:e.target.value,confirmed_person_id:null,proposed_person_id:null})}/></label><label>시작(초)<input type="number" step="0.001" value={s.start_ms/1000} onChange={e=>change(s.segment_id,{start_ms:Math.round(+e.target.value*1000)})}/></label><label>종료(초)<input type="number" step="0.001" value={s.end_ms/1000} onChange={e=>change(s.segment_id,{end_ms:Math.round(+e.target.value*1000)})}/></label></div><textarea aria-label={`녹취 ${n+1}`} rows={2} value={s.text} onChange={e=>change(s.segment_id,{text:e.target.value})}/><div className="segment-actions">{s.proposed_person_id&&profiles.find(p=>p.person_id===s.proposed_person_id)&&!s.confirmed_person_id&&<button onClick={()=>{const p=profiles.find(p=>p.person_id===s.proposed_person_id)!;change(s.segment_id,{confirmed_person_id:p.person_id,speaker_name:`${p.display_name}${p.role?" "+p.role:""}${p.company?" ("+p.company+")":""}`});}}>후보 확인: {profiles.find(p=>p.person_id===s.proposed_person_id)?.display_name}</button>}<select aria-label="구간 검토 상태" value={s.review_status} onChange={e=>change(s.segment_id,{review_status:e.target.value as Segment["review_status"]})}><option value="unreviewed">검토 전</option><option value="confirmed">검토 완료</option><option value="uncertain">불확실</option></select><label className="checkbox"><input type="checkbox" checked={s.overlap} onChange={e=>change(s.segment_id,{overlap:e.target.checked})}/>겹침 발화</label><button onClick={()=>{const m=Math.floor((s.start_ms+s.end_ms)/2);setSegments(ss=>ss.flatMap(x=>x.segment_id===s.segment_id?[{...x,end_ms:m,timing_provenance:"manual" as const},{...x,segment_id:crypto.randomUUID(),start_ms:m,text:"",timing_provenance:"manual" as const,local_speaker_id:`${x.local_speaker_id}-분할`}]:[x]));edit();}}>구간 분할</button>{!serverProcessing&&<><select aria-label="기준 음성을 추가할 화자" value={profileTargets[s.segment_id]??""} onChange={e=>setProfileTargets({...profileTargets,[s.segment_id]:e.target.value})}><option value="">새 화자로 등록</option>{profiles.map(p=><option key={p.person_id} value={p.person_id}>{p.display_name} · 기준 음성 추가</option>)}</select><button disabled={!s.speaker_name||s.review_status!=="confirmed"||s.overlap||dirty} onClick={()=>run(async()=>{const selected=profiles.find(p=>p.person_id===profileTargets[s.segment_id]);await api(`jobs/${job.id}/profiles`,"POST",{...(selected?{person_id:selected.person_id}:{}),segment_ids:[s.segment_id],display_name:selected?.display_name??s.speaker_name,role:selected?.role??"",company:selected?.company??"",confirmed_single_speaker:true});setNotice("PC에 화자 등록을 전달했습니다.");})}>이 화자 PC에 등록</button></>}</div></div></article>):<div className="empty-state"><AudioLines size={38}/><h3>{job.error?"음성 처리에 확인이 필요합니다.":!connected?serverProcessing?"서버 응답을 기다리고 있습니다.":"PC 연결을 기다리고 있습니다.":"음성을 정리하고 있습니다."}</h3><p>{job.error?.message??(!connected?serverProcessing?"서버 처리 상태에서 최근 응답을 확인하세요. 현재 녹취 결과는 없습니다.":"PC 연결 및 설정에서 작업 프로그램의 연결 상태를 확인하세요. 현재 녹취 결과는 없습니다.":"처리 결과가 도착하면 시간 구간별 녹취가 나타납니다.")}</p></div>}{visibleSegments<filteredSegments.length&&<button className="more-segments" onClick={()=>setVisibleSegments(n=>n+50)}>현재 {visibleSegments} / {filteredSegments.length} 구간 · 다음 50개 보기</button>}<div className="editor-bottom">{stt?<><span>{dirty?"미저장 변경이 있습니다. 저장한 뒤 TXT를 내려받으세요.":`저장된 전체 녹취 v${job.transcript_revision} · 화자·시간·원문 포함`}</span></>:<><span>{serverProcessing?"서버의 회의록 문장 생성은 아직 구성되지 않았습니다. 저장한 녹취를 TXT로 내려받을 수 있습니다.":"회의록은 저장한 검토 버전에서 작성합니다."}</span><button className="button primary" disabled={busy||dirty||!segments.length||!generationAvailable} onClick={()=>run(async()=>{await api(`jobs/${job.id}/minutes`,"POST",{transcript_revision:job.transcript_revision});await load(job.id);setTab("minutes");})}><FileText size={16}/>회의록 작성</button></>}</div></section>}
 {!stt&&tab==="minutes"&&<section className="card minutes-card"><div className="editor-toolbar"><div><h2>회의록 검토</h2><p>{job.draft?`녹취 v${job.draft.transcript_revision} 기준 · ${job.draft.generation_mode}`:serverProcessing?"회의록 문장 생성은 아직 구성되지 않았습니다.":"검토한 녹취를 저장한 뒤 회의록을 작성하세요."}{job.draft&&job.draft.transcript_revision!==job.transcript_revision&&" · 이전 녹취 버전의 초안"}</p></div><div className="button-row"><button className="button secondary" onClick={()=>setMinutesMode(m=>m==="preview"?"edit":"preview")}>{minutesMode==="preview"?"직접 편집":"미리보기"}</button><button className="text-link" disabled={!dirty||busy} onClick={()=>run(()=>load(job.id))}>변경 취소</button><button className="button secondary" disabled={!job.draft||!dirty||busy} onClick={saveDraft}><Save size={16}/>저장</button>{job.draft&&<a className="button secondary" href={`/api/jobs/${job.id}/download`} download><Download size={16}/>Markdown</a>}</div></div>{missingMetadata(job.metadata,job.meeting_type).length>0&&<div className="inline-note">확인할 정보: {missingMetadata(job.metadata,job.meeting_type).map(k=>labels[k]).join(", ")} · 미확인 값은 추측하지 않습니다.</div>}{job.draft&&versions.filter(v=>v.kind==="minutes").length>0&&<div className="version-picker"><label>이전 버전 비교 <select defaultValue="" onChange={e=>run(async()=>{if(!e.target.value){setComparison("");return;}const previous=await api(`jobs/${job.id}/revisions/minutes/${e.target.value}`);setComparison(previous.content);})}><option value="">버전 선택</option>{versions.filter(v=>v.kind==="minutes").map(v=><option key={v.revision} value={v.revision}>v{v.revision} · {new Date(v.created_at).toLocaleString("ko-KR")}</option>)}</select></label>{comparison&&<><pre>{comparison}</pre><button className="text-link" onClick={()=>{setDraft(comparison);setMinutesMode("edit");setComparison("");edit();}}>이 버전을 편집기에 가져오기</button></>}</div>}{job.draft?(minutesMode==="preview"?<MarkdownView content={draft}/>:<textarea className="markdown-editor" aria-label="회의록 Markdown 편집" value={draft} onChange={e=>{setDraft(e.target.value);edit();}}/>):<div className="empty-state"><FileText size={38}/><h3>{job.state==="generating"?"회의록 초안 작성 중":serverProcessing?"회의록 자동 생성 미구성":"첫 초안을 기다리고 있습니다."}</h3><p>{job.error?.message||(serverProcessing?"녹취 검토와 TXT 다운로드는 이용할 수 있습니다.":"녹취 검토 탭에서 회의록 작성을 시작하세요.")}</p></div>}<div className="editor-bottom"><span>Notion 인증은 기존 PC에만 유지되며 서버에서는 실행하지 않습니다. <a className="text-link" href={`/api/jobs/${job.id}/export-bundle`} download>로컬 내보내기용 파일</a></span><button className="text-link" disabled={busy||dirty||!segments.length||!generationAvailable} onClick={()=>run(async()=>{await api(`jobs/${job.id}/minutes`,"POST",{transcript_revision:job.transcript_revision});await load(job.id);})}><RefreshCw size={15}/>새 초안 작성</button></div></section>}
 {!stt&&tab==="info"&&<section className="card details-card"><h2>회의 정보 확인</h2><p>{metaSuggestions.length||candidates.length?"추정 표시가 붙은 값은 파일 이름, 녹취의 화자 이름, 녹취 대화로 채운 것입니다. 근거를 보고 맞는지 확인한 뒤 저장하세요. 저장하기 전에는 회의록에 들어가지 않습니다.":"직접 입력 칸을 채운 뒤 저장하세요. 모르는 값은 비워 두면 회의록에 (미확인)으로 남습니다."} 회의 일시는 한국시간(Asia/Seoul)입니다.</p><div className="metadata-form">{Object.entries(labels).filter(([k])=>k!=="week"||job.meeting_type==="weekly").map(([k,l])=>{const key=k as keyof Metadata,value=meta[key],s=metaSuggestions.find(x=>x.key===key),first=prefilled.find(x=>x.key===key),pending=savedMissing.includes(k)&&!!value.trim()&&(value===s?.value||value===first?.value),stale=pending&&value!==s?.value,shown=value===s?.value?s:first,source=shown?.source,older=pending&&!stale&&shown?.from_revision,offer=!!s&&value!==s.value&&(!value.trim()||pending),missing=!value.trim()&&savedMissing.includes(k);return <div key={k} className={`meta-field ${k==="attendees"?"full":""} ${pending?"suggested":""} ${missing&&!offer?"needs-input":""}`}><label><span className="field-label">{l}{pending&&source&&<span className={`field-source ${stale||older?"missing":""}`}>{suggestionSourceLabels[source]} · {stale?"녹취가 바뀌어 다시 확인":older?`이전 녹취 v${older} 기준, 다시 확인`:"저장 전 확인"}</span>}{missing&&!offer&&<span className="field-source missing">{k==="attendees"?"직접 입력 또는 녹취 화자 이름 저장":"직접 입력"}</span>}</span>{k==="meeting_format"?<select value={meta.meeting_format} onChange={e=>{setMeta({...meta,meeting_format:e.target.value});edit();}}><option value="">선택 입력</option>{meta.meeting_format&&!(MEETING_FORMATS as readonly string[]).includes(meta.meeting_format)&&<option value={meta.meeting_format}>{meta.meeting_format}</option>}{MEETING_FORMATS.map(v=><option key={v} value={v}>{v}</option>)}</select>:k==="attendees"?<textarea rows={3} value={meta.attendees} placeholder="이름 직책 (회사) · 고객사 참석자부터 줄바꿈" onChange={e=>{setMeta({...meta,attendees:e.target.value});edit();}}/>:<input type={k==="datetime"?"datetime-local":"text"} value={meta[key]} onChange={e=>{setMeta({...meta,[k]:e.target.value});edit();}}/>}</label>{pending&&shown?.quote&&<Evidence quote={shown.quote} label={l} segment={job.segments.find(x=>x.segment_id===shown.segment_ids?.[0])} onPlay={play}/>}{offer&&<button className="text-link suggest-apply" onClick={()=>{setMeta({...meta,[key]:s!.value});edit();}}>{stale?"새 추정값으로 바꾸기":`${suggestionSourceLabels[s!.source]} 값 넣기`}: {s!.value.replace("T"," ").replace(/\n+/g,", ")}</button>}</div>;})}</div>{candidates.length>0&&<div className="attendee-candidates"><strong>녹취에서 들은 참석 후보</strong><p>회의 자리에서 스스로 소개하거나 인사한 사람입니다. 맞는 사람만 참석자에 넣으세요.</p>{candidates.map(c=><div key={c.value} className="candidate"><span className="candidate-name">{c.value}{c.from_revision?<span className="field-source missing">이전 녹취 v{c.from_revision} 기준</span>:null}</span><Evidence quote={c.quote!} label={c.value} segment={job.segments.find(x=>x.segment_id===c.segment_ids?.[0])} onPlay={play}/><button className="text-link" aria-label={`${c.value} 후보 넣기`} disabled={meta.attendees.split("\n").some(line=>line.trim()===c.value)||meta.attendees.trim().length+c.value.length+1>4000} onClick={()=>{setMeta({...meta,attendees:[meta.attendees.trim(),c.value].filter(Boolean).join("\n")});edit();}}>후보 넣기</button></div>)}</div>}{job.upload_complete&&(candidates.length>0||metaSuggestions.some(x=>x.quote))&&<audio ref={audio} className="evidence-audio" controls preload="none" src={`/api/jobs/${job.id}/audio`}/>}<button className="button primary" onClick={()=>run(async()=>{await api(`jobs/${job.id}/metadata`,"PATCH",{expected_revision:job.revision,metadata:wireMetadata(meta)});await load(job.id);})}><Save size={16}/>확인한 정보 저장</button></section>}
 <button className="text-link delete-job" onClick={()=>{if(window.confirm(serverProcessing?"서버에 저장된 음성과 결과를 삭제하고 작업기 임시 사본 삭제를 예약할까요? 업로드한 원본 파일은 유지됩니다.":stt?"서버 음성과 녹취를 삭제하고 PC 사본 삭제를 예약할까요? 업로드한 원본 파일은 유지됩니다.":"클라우드 음성과 결과를 삭제하고 PC 사본 삭제를 예약할까요? 원본과 Notion 페이지는 유지됩니다."))run(async()=>{await api(`jobs/${job.id}`,"DELETE");clearUploadResume(job.id);clearQueueJob(job.id);setJob(null);setMeta(newMeeting());setView("new");await refresh();});}}><Trash2 size={15}/>작업 삭제</button></>}
 <footer>{stt?"음성의 원문을 남기고, 확인되지 않은 화자는 추측하지 않습니다.":"회의의 맥락은 남기고, 확인되지 않은 사실은 더하지 않습니다."}</footer></fieldset></main></div></div>;
